  "id": "migration-record-in-docs",
  "severity": "blocking",
  "since": "2026-09-06",
  "failureMessage": "a migration's plan, status and remaining work live in its tracking issue, never a MIGRATION.md beside the design",
  "forbidTrackedPathsMatching": [
    {
      "match": "/(^|\\/)docs\\/.*MIGRATION\\.md$/",
      "what": "a MIGRATION.md beside a design: {path}",
      "fix": "move what is still live into the tracking issue (writing-migration-plans) and delete the file"
    }
  ]
}
{
  "id": "design-doc-status-banner",
  "severity": "advisory",
  "since": "2026-09-08",
  "failureMessage": "an initiative's DESIGN.md reads as a description of how the system works; without a status on its first screen a reader takes an unbuilt proposal for the current state",
  "scanFiles": "/(^|\\/)docs\\/[^/]+\\/DESIGN\\.md$/",
  "scanTracked": true,
  "checkEachFile": [
    {
      "require": "/^(?:.*\\n){0,6}> \\*\\*Status: (?:not implemented|in flight)\\.\\*\\* /",
      "what": "carries no status banner in its first seven lines",
      "fix": "open it with `> **Status: not implemented.** \u2026` or `> **Status: in flight.** \u2026`; a built system's design doc has no third status \u2014 delete it whole instead"
    }
  ]
}
{
  "id": "check-sweep-read-blocking-only",
  "severity": "advisory",
  "since": "2026-09-15",
  "scope": "action",
  "failureMessage": "a check inside its two-week since grace reports ADVISORY, so a BLOCKING-only filter reads your own new check as silent and the violations it found as none",
  "guardToolCalls": [
    {
      "tool": "Bash",
      "inputField": "command",
      "match": "/check_the_(?:world|work)\\.mjs[^\\n]*[|;\\n][^\\n]*\\b(?:grep|egrep|rg)\\b[^\\n]*BLOCKING/",
      "what": "a sweep read through a BLOCKING-only filter: \"{match}\"",
      "fix": "read the whole output \u2014 the advisory lines carry every check still inside its since grace, your own new one among them"
    }
  ]
}
{
  "id": "subagent-branch-named-git",
  "severity": "blocking",
  "since": "2026-09-16",
  "scope": "action",
  "failureMessage": "a worktree-isolated agent's shell guard refuses a command over the word git, so a branch carrying it in its own name cannot be created there under any spelling",
  "guardToolCalls": [
    {
      "tool": "Agent",
      "inputField": "prompt",
      "match": "/(?:branch\\s+named|branch\\s+-m|switch\\s+-c|checkout\\s+-b)\\s+[`'\"]?(?:[\\w.\\/-]*[\\/_-])?git[\\w.\\/-]*/",
      "inputMatches": "/\"isolation\"\\s*:\\s*\"worktree\"/",
      "what": "a worktree-isolated dispatch mandating a branch named over git: \"{match}\"",
      "fix": "name the branch without the word git (perf/fixtures, not perf/git-fixtures) \u2014 the child cannot rename it afterwards either"
    }
  ]
}

