1	import { test } from 'node:test';
2	import assert from 'node:assert/strict';
3	import { fileURLToPath } from 'node:url';
4	import { execFileSync } from 'node:child_process';
5	import { makeRepo, cleanup } from '../../../../../engine-tests/helpers.mjs';
6	import { buildContext } from '../../../../../engine/checks/helpers/repo-context.mjs';
7	import { loadDeclaredChecks } from '../../../../../engine/checks/helpers/pattern-rules.mjs';
8	
9	const rule = loadDeclaredChecks(
10	  fileURLToPath(new URL('..', import.meta.url)),
11	).find((r) => r.id === 'design-doc-status-banner');
12	
13	const run = (root) => rule.run(buildContext({ root, mode: 'all' }));
14	const at = (files) => makeRepo({ base: files });
15	const BANNER = '> **Status: not implemented.** A proposal, not a description of this repository.';
16	
17	test('design-doc-status-banner: a banner on the first screen passes', () => {
18	  const root = at({ 'docs/thing/DESIGN.md': `# Thing — design\n\n${BANNER}\n\nBody.\n` });
19	  try { assert.deepEqual(run(root), []); } finally { cleanup(root); }
20	});
21	
22	test('design-doc-status-banner: "in flight" is the other accepted status', () => {
23	  const root = at({ 'docs/thing/DESIGN.md': '# Thing\n\n> **Status: in flight.** Half of it exists.\n' });
24	  try { assert.deepEqual(run(root), []); } finally { cleanup(root); }
25	});
26	
27	test('design-doc-status-banner: a doc with no banner is reported', () => {
28	  const root = at({ 'docs/thing/DESIGN.md': '# Thing — design\n\nStraight into the mechanism.\n' });
29	  try {
30	    const findings = run(root);
31	    assert.equal(findings.length, 1);
32	    assert.match(findings[0].fix, /Status: not implemented/);
33	  } finally { cleanup(root); }
34	});
35	
36	// A warning below the fold is not a warning: the reader who skims the opening
37	// paragraphs is exactly the reader who takes a proposal for the current state.
38	test('design-doc-status-banner: a banner past the first screen does not count', () => {
39	  const root = at({ 'docs/thing/DESIGN.md': `# Thing\n\n${'Filler paragraph.\n\n'.repeat(6)}${BANNER}\n` });
40	  try { assert.equal(run(root).length, 1); } finally { cleanup(root); }
41	});
